const q=s=>document.querySelector(s),qa=s=>[...document.querySelectorAll(s)];
const lang=localStorage.getItem('lit-lang')||'en';
function tr(){
  const t=copy[localStorage.getItem('lit-lang')||'en'];
  qa('[data-t]').forEach(el=>{el.innerHTML=t[el.dataset.t]||el.innerHTML});
  document.documentElement.lang=localStorage.getItem('lit-lang')||'en';
  document.querySelectorAll('.brand').forEach(brand=>{
    if(brand.dataset.logoApplied)return;
    brand.dataset.logoApplied='true';
    brand.classList.add('brand-image');
    brand.innerHTML='<img src="/logo-Litbuy.png" alt="LITBUYY">';
  });
  const faqItems=qa('.faq details');
  if(faqItems[4]){
    faqItems[4].querySelector('summary').textContent='How should I use listed prices?';
    faqItems[4].querySelector('p').textContent='Homepage product cards show USD estimates based on the linked main-site price. Confirm the current price, options and availability on the product page.';
  }
  if(!q('#litbuyy-controls')){
    const controls=document.createElement('style');
    controls.id='litbuyy-controls';
    controls.textContent='.brand.brand-image{display:flex;align-items:center;line-height:0}.brand.brand-image img{display:block;width:136px;height:auto}.footer .brand.brand-image img{width:154px}.lang,.lang:focus,.lang option{background:#000!important;color:#fff!important}.lang{border-color:rgba(216,213,226,.58)!important}@media(max-width:860px){.brand.brand-image img{width:118px}.footer .brand.brand-image img{width:136px}}';
    document.head.append(controls);
  }
  if(!window.__litSearchBound){
    window.__litSearchBound=true;
    document.addEventListener('submit',event=>{
      if(!event.target.matches('#search-form,#muse-search'))return;
      event.preventDefault();event.stopImmediatePropagation();
      const term=event.target.querySelector('input')?.value.trim();
      if(term)window.location.assign('https://findspreadsheet.com/search.html?keywords='+encodeURIComponent(term)+'&channelid=2');
    },true);
  }
  if((location.pathname.replace(/\/$/,'')||'/')==='/'&&!window.__litProductShowcaseBound){
    window.__litProductShowcaseBound=true;
    let attempts=0;
    const mountProducts=()=>{
      if(q('.muse-footer-grid')){import('/product-showcase.js').then(module=>module.mount());return}
      if(++attempts<30)setTimeout(mountProducts,32);
    };
    mountProducts();
  }
  if(!window.__litResearchBound){
    window.__litResearchBound=true;
    import('/litbuy-research.js').then(module=>module.mount());
  }
  import('/language-content.js').then(module=>module.apply(localStorage.getItem('lit-lang')||'en'));
}
function goSearch(e){e?.preventDefault();const term=q('#site-search').value.trim();if(term)window.location.assign('https://findspreadsheet.com/search.html?keywords='+encodeURIComponent(term)+'&channelid=2')}
document.addEventListener('DOMContentLoaded',()=>{const s=q('#language');if(s){s.value=lang;s.onchange=()=>{localStorage.setItem('lit-lang',s.value);tr()}}q('#search-form')?.addEventListener('submit',goSearch);q('.mobile-toggle')?.addEventListener('click',()=>q('.navlinks').classList.toggle('open'));const theme=document.createElement('style');theme.textContent=':root{--paper:#000;--ink:#F8F5FA;--line:#D8D5E2;--purple:#A855F7;--violet:#8A2BE2}.database,.primary{box-shadow:0 0 0 1px rgba(168,85,247,.42),0 0 18px rgba(168,85,247,.36)}.database:hover,.primary:hover{background:var(--violet);box-shadow:0 0 0 2px rgba(168,85,247,.58),0 0 28px rgba(168,85,247,.58)}.entry:hover,.entry:focus-visible{background:rgba(168,85,247,.07);box-shadow:inset 3px 0 0 var(--purple);outline:0}.feature.purple{box-shadow:0 0 0 2px rgba(168,85,247,.68),0 0 30px rgba(168,85,247,.38)}.card{border:1px solid transparent;transition:border-color .18s,box-shadow .18s,transform .18s}.card:hover,.card:focus-within{border-color:var(--purple);box-shadow:0 0 0 2px rgba(168,85,247,.4),0 0 24px rgba(168,85,247,.24);transform:translateY(-2px)}';document.head.append(theme);const first=q('.feature-grid a:first-child');if(first){first.href='https://findspreadsheet.com';first.classList.remove('dark');first.classList.add('purple');first.innerHTML='<span class="label">Main database</span><h3>Open the complete product index.</h3><p>Search the main database directly when you already know what you need.</p><span class="label">OPEN DATABASE ↗</span>'}const add=q('.article .primary');if(add)add.textContent='ADD TO BAG';tr();import('/midnight-gallery.js').then(m=>{m.init({q});tr()})});
